import org.apache.commons.beanutils.BeanUtils;
import org.apache.commons.beanutils.ConvertUtils;
import org.apache.commons.beanutils.PropertyUtils;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Array;

public void setProperty(Object bean, String name, Object value) throws InvocationTargetException, IllegalAccessException {
    if (bean == null || name == null) {
        return;
    }

    try {
        Class<?> propertyType = PropertyUtils.getPropertyType(bean, name);
        Object convertedValue = value;

        if (value != null && !propertyType.isInstance(value)) {
            if (propertyType.isArray() && value instanceof String) {
                convertedValue = ConvertUtils.convert(value, propertyType.getComponentType());
            } else if (propertyType.isArray() && value instanceof String[]) {
                String[] values = (String[]) value;
                Object arrayValue = Array.newInstance(propertyType.getComponentType(), values.length);
                for (int i = 0; i < values.length; i++) {
                    Object convertedElement = ConvertUtils.convert(values[i], propertyType.getComponentType());
                    Array.set(arrayValue, i, convertedElement);
                }
                convertedValue = arrayValue;
            } else {
                convertedValue = ConvertUtils.convert(value, propertyType);
            }
        }

        PropertyUtils.setProperty(bean, name, convertedValue);
    } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
        throw e;
    } catch (Exception e) {
        throw new InvocationTargetException(e, "Error setting property: " + name);
    }
}

